import os
from typing import Any, Dict, List, Union

import boto3


def _image_bytes_from_input(image_input: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(image_input, (bytes, bytearray)):
        return bytes(image_input)
    if isinstance(image_input, str):
        if image_input.startswith("http://") or image_input.startswith("https://"):
            import urllib.request

            with urllib.request.urlopen(image_input) as response:
                return response.read()
        with open(image_input, "rb") as f:
            return f.read()
    raise TypeError("image_input must be a local file path, URL, bytes, or bytearray")


def detect_labels(image_input: Union[str, bytes, bytearray], max_labels: int = 20, min_confidence: float = 50.0) -> List[Dict[str, Any]]:
    """
    Detect labels/objects in a static image using Amazon Rekognition.

    Returns a list of dictionaries with:
      - Name
      - Confidence
      - Parents
    """
    region = os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    rekognition = boto3.client("rekognition", region_name=region)

    image_bytes = _image_bytes_from_input(image_input)
    response = rekognition.detect_labels(
        Image={"Bytes": image_bytes},
        MaxLabels=int(max_labels),
        MinConfidence=float(min_confidence),
    )

    labels: List[Dict[str, Any]] = []
    for label in response.get("Labels", []):
        labels.append(
            {
                "Name": label.get("Name"),
                "Confidence": label.get("Confidence"),
                "Parents": [parent.get("Name") for parent in label.get("Parents", []) if parent.get("Name")],
            }
        )
    return labels


def detect_text(image_input: Union[str, bytes, bytearray], min_confidence: float = 50.0) -> List[Dict[str, Any]]:
    """
    Detect text in a static image using Amazon Rekognition.

    Returns a list of dictionaries with:
      - Text
      - Confidence
      - Type
    """
    region = os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    rekognition = boto3.client("rekognition", region_name=region)

    image_bytes = _image_bytes_from_input(image_input)
    response = rekognition.detect_text(
        Image={"Bytes": image_bytes},
    )

    texts: List[Dict[str, Any]] = []
    for item in response.get("TextDetections", []):
        confidence = item.get("Confidence", 0.0)
        if confidence is not None and confidence >= float(min_confidence):
            texts.append(
                {
                    "Text": item.get("DetectedText"),
                    "Confidence": confidence,
                    "Type": item.get("Type"),
                }
            )
    return texts


def analyze_image(image_input: Union[str, bytes, bytearray], max_labels: int = 20, min_confidence: float = 50.0) -> Dict[str, Any]:
    """
    Analyze a static image for labels and text using Amazon Rekognition.
    """
    return {
        "labels": detect_labels(image_input, max_labels=max_labels, min_confidence=min_confidence),
        "text": detect_text(image_input, min_confidence=min_confidence),
    }
